def main(filters):
    BUCKETS = [(0, 0, 'not_due'), (1, 30, 'd1_30'), (31, 60, 'd31_60'), (61, 90, 'd61_90'), (91, 10 ** 6, 'd90_plus')]

    def bucket(days_overdue):
        if days_overdue <= 0:
            return 'not_due'
        for lo, hi, key in BUCKETS[1:]:
            if lo <= days_overdue <= hi:
                return key
        return 'd90_plus'

