def main(filters):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from production/cutting.py and production/stock.py: roll suggestion for a cut plan, bundle numbering for a lay, kit components, and the Stock Entries
    # of the production floor (fabric issue, remnant return). Needs lib_mat.py (to_metres) for the cut plan only.
    OK_STATUS = ("Accepted", "Accepted by Lot")


    def setting(field):
        return frappe.db.get_single_value("Apparel Settings", field)


    def roll_available(batch, warehouse, item_code):
        """Metres of a roll (Batch) in a warehouse. 0 when the warehouse is unknown."""
        if not warehouse:
            return 0
        return frappe.utils.flt(frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=batch, warehouse=warehouse, item_code=item_code))


    def roll_info(batch):
        b = frappe.db.get_value("Batch", batch, ["item", "apparel_roll_no", "apparel_dye_lot", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status",
                                                  "apparel_shrinkage_warp_pct", "apparel_shrinkage_weft_pct"], as_dict=True)
        if not b:
            frappe.throw("Roll %s not found." % batch)
        return b


    def required_components(card, colour):
        """Fabric roles that make up a garment of this colour on the production card (Shell, Lining, ...)."""
        roles = frappe.get_all("Production Card Fabric", filters={"parent": card, "colour": colour}, pluck="material_role")
        out = []
        for r in (roles or ["Shell"]):
            if r not in out:
                out.append(r)
        return sorted(out)


    def suggest_rolls(plan_name):
        """Allocate the rolls in the Cutting WIP warehouse to the lays of a cut plan: group by shade band, then width, then longest roll first. Nothing is saved."""
        flt = frappe.utils.flt
        plan = frappe.get_doc("Cut Plan", plan_name)
        wh = setting("cutting_wip_warehouse")
        pool = []
        for b in frappe.get_all("Batch", filters={"item": plan.fabric_item, "disabled": 0},
                                fields=["name", "apparel_roll_no", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status", "apparel_dye_lot"]):
            if b.apparel_inspection_status not in OK_STATUS:
                continue
            avail = roll_available(b.name, wh, plan.fabric_item)
            if avail > 0:
                pool.append({"batch": b.name, "roll_no": b.apparel_roll_no, "shade": b.apparel_shade_band or "", "width": flt(b.apparel_width_cm), "length": avail, "dye_lot": b.apparel_dye_lot})
        out = []
        short = []
        spread = flt(setting("max_width_spread_cm") or 1)
        for lay in sorted(plan.lays, key=lambda l: l.lay_no):
            need = flt(lay.planned_plies) * flt(lay.marker_length_m)
            cands = [r for r in pool if (not (lay.shade_band or "").strip() or r["shade"] == lay.shade_band)
                     and (not flt(lay.width_group_cm) or abs(r["width"] - flt(lay.width_group_cm)) <= spread)
                     and (not flt(lay.marker_width_cm) or not r["width"] or r["width"] >= flt(lay.marker_width_cm))]
            if not (lay.shade_band or "").strip() and cands:    # no shade named: keep to the shade band of the longest roll
                first = sorted(cands, key=lambda r: -r["length"])[0]
                cands = [r for r in cands if r["shade"] == first["shade"] and abs(r["width"] - first["width"]) <= spread]
            cands = sorted(cands, key=lambda r: -r["length"])
            taken = []
            got = 0.0
            for r in cands:
                if got >= need - 1e-9:
                    break
                use = min(r["length"], need - got)
                plies = int(frappe.utils.floor(use / flt(lay.marker_length_m))) if flt(lay.marker_length_m) else 0
                if plies <= 0:
                    continue
                metres = plies * flt(lay.marker_length_m)
                taken.append({"batch": r["batch"], "roll_no": r["roll_no"], "plies": plies, "metres": round(metres, 3), "shade": r["shade"], "width": r["width"]})
                got = got + metres
                r["length"] = r["length"] - metres
            out.append({"lay_no": lay.lay_no, "needed_m": round(need, 3), "allocated_m": round(got, 3), "rolls": taken})
            if got < need - 1e-9:
                short.append({"lay_no": lay.lay_no, "short_m": round(need - got, 3)})
        left = [{"batch": r["batch"], "roll_no": r["roll_no"], "metres": round(r["length"], 3), "shade": r["shade"]} for r in pool if r["length"] > 1e-9]
        return {"lays": out, "unallocated": left, "short": short}


    def next_ply(card):
        """First free ply number on a production card (sticker numbers never repeat on a card)."""
        return frappe.utils.cint(frappe.db.sql("select ifnull(max(ply_to), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1


    def chunks(first, last, size):
        """Ply ranges [[from, to], ...] of at most `size` plies covering first..last."""
        size = max(frappe.utils.cint(size), 1)
        out = []
        a = first
        while a <= last:
            b = min(a + size - 1, last)
            out.append([a, b])
            a = b + 1
        return out


    def new_bundle(lay, card, size, body, ply_from, ply_to, qty, rolls, kit_key, short, bundle_no):
        if bundle_no is None:
            bundle_no = frappe.utils.cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1
        d = frappe.get_doc({"doctype": "Cut Bundle", "production_card": card, "lay_report": lay.name, "colour": lay.colour, "size": size, "component": lay.component or "Shell",
                            "purpose": lay.purpose, "bundle_no": bundle_no, "body_no": body, "ply_from": ply_from, "ply_to": ply_to, "qty": qty, "shade_band": lay.shade_band,
                            "roll_nos": rolls, "kit_key": kit_key, "status": "Cut", "is_short": frappe.utils.cint(short)})
        d.insert(ignore_permissions=True)
        return d.name


    def make_bundles(lay):
        """Create the Cut Bundles of a submitted Lay Report. A paired (lining, pocketing) lay mirrors the ply ranges of its shell lay so every component of a garment
        carries the same ply number. Returns the bundle names."""
        cint = frappe.utils.cint
        card = lay.production_card
        size_bundle = cint(frappe.db.get_value("Production Card", card, "bundle_size")) or cint(setting("bundle_size")) or 20
        rolls = ", ".join([r.roll_no or r.batch for r in lay.rolls])
        names = []
        if lay.paired_with:
            src = frappe.get_all("Cut Bundle", filters={"lay_report": lay.paired_with, "status": ["!=", "Voided"]}, order_by="bundle_no",
                                 fields=["size", "body_no", "ply_from", "ply_to", "qty", "kit_key", "is_short", "bundle_no"])
            for b in src:
                names.append(new_bundle(lay, card, b.size, b.body_no, b.ply_from, b.ply_to, b.qty, rolls, b.kit_key, b.is_short, None))
            return names
        first = next_ply(card)
        plies = cint(lay.total_plies)
        last = first + plies - 1
        n = cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0])
        for s in lay.sizes:
            for body in range(1, max(cint(s.ratio), 1) + 1):
                for ab in chunks(first, last, size_bundle):
                    qty = ab[1] - ab[0] + 1
                    key = "%s|%s|%s-%s|%s" % (lay.colour, s.size, ab[0], ab[1], body)
                    n = n + 1
                    names.append(new_bundle(lay, card, s.size, body, ab[0], ab[1], qty, rolls, key, 1 if qty < size_bundle else 0, n))
        return names


    def void_bundles(lay_name):
        """Cancel of a lay: bundles are voided (their numbers are never reused). Blocked once any bundle left the cutting room."""
        moved = frappe.get_all("Cut Bundle", filters={"lay_report": lay_name, "status": ["not in", ("Cut", "Voided")]}, pluck="name")
        if moved:
            frappe.throw("Bundles %s have already left the cutting room. Take them back before cancelling the lay." % ", ".join(moved[:5]))
        for n in frappe.get_all("Cut Bundle", filters={"lay_report": lay_name}, pluck="name"):
            frappe.db.set_value("Cut Bundle", n, "status", "Voided", update_modified=False)


    def kit_missing(bundle_names):
        """For shell bundles about to go to a line: the kit keys whose lining / pocketing bundles are missing."""
        missing = []
        for n in bundle_names:
            b = frappe.db.get_value("Cut Bundle", n, ["production_card", "colour", "component", "kit_key"], as_dict=True)
            if b.component != "Shell":
                continue
            for comp in required_components(b.production_card, b.colour):
                if comp == "Shell":
                    continue
                if not frappe.db.exists("Cut Bundle", {"production_card": b.production_card, "kit_key": b.kit_key, "component": comp, "status": ["!=", "Voided"]}):
                    missing.append("%s (%s)" % (b.kit_key, comp))
        return missing


    def make_transfer(company, rows, kind, card, remarks, submit):
        """Material Transfer for `rows` = dicts(item_code, qty, s_warehouse, t_warehouse, batch_no). Returns the name, or None when nothing moves.
        The entry is tagged with the production card and the kind so reports can sum it."""
        rows = [r for r in rows if frappe.utils.flt(r.get("qty")) > 0]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = company
        se.apparel_production_card = card
        se.apparel_issue_kind = kind
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": r["s_warehouse"], "t_warehouse": r["t_warehouse"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = remarks
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_entry(name):
        if name and frappe.db.exists("Stock Entry", name):
            d = frappe.get_doc("Stock Entry", name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc("Stock Entry", name, ignore_permissions=True, force=True)


    def moved_qty(card, kind, item_code):
        """Quantity moved by submitted entries of this kind for a production card (optionally one item)."""
        cond = ""
        args = [card, kind]
        if item_code:
            cond = " and d.item_code = %s"
            args.append(item_code)
        return frappe.utils.flt(frappe.db.sql("select ifnull(sum(d.qty), 0) from `tabStock Entry Detail` d join `tabStock Entry` s on s.name = d.parent "
                                              "where s.docstatus = 1 and s.apparel_production_card = %s and s.apparel_issue_kind = %s" + cond, tuple(args))[0][0])


    def refresh_issued(card):
        """Write the issued metres onto the fabric rows of an issued card."""
        done = []
        for row in frappe.get_all("Production Card Fabric", filters={"parent": card}, fields=["name", "fabric_item"], order_by="idx"):
            if not row.fabric_item or row.fabric_item in done:
                continue
            done.append(row.fabric_item)
            frappe.db.set_value("Production Card Fabric", row.name, "issued_m", moved_qty(card, "Fabric Issue", row.fabric_item), update_modified=False)


    def issue_fabric_entry(card_name, rolls):
        """Issue rolls from the fabric store to Cutting WIP. rolls = [{batch_no, qty}]. Only accepted rolls leave the store."""
        card = frappe.get_doc("Production Card", card_name)
        if card.docstatus != 1:
            frappe.throw("Issue the production card first.")
        if not rolls:
            frappe.throw("Choose at least one roll to issue.")
        src = setting("store_warehouse_fabric")
        dst = setting("cutting_wip_warehouse")
        if not src or not dst:
            frappe.throw("Set the fabric store and Cutting WIP warehouses in Apparel Settings.")
        items = []
        fabrics = [f.fabric_item for f in card.fabrics]
        for r in rolls:
            b = frappe.db.get_value("Batch", r["batch_no"], ["item", "apparel_inspection_status", "apparel_roll_no"], as_dict=True)
            if not b:
                frappe.throw("Roll %s not found." % r["batch_no"])
            if b.apparel_inspection_status not in OK_STATUS:
                frappe.throw("Roll %s is %s. Only accepted rolls can be issued to cutting." % (b.apparel_roll_no or r["batch_no"], b.apparel_inspection_status or "not inspected"))
            if b.item not in fabrics:
                frappe.throw("Roll %s is %s, which is not a fabric of production card %s." % (b.apparel_roll_no or r["batch_no"], b.item, card.name))
            if frappe.utils.flt(r.get("qty")) <= 0:
                frappe.throw("Roll %s: enter the metres to issue (above zero)." % (b.apparel_roll_no or r["batch_no"]))
            items.append({"item_code": b.item, "qty": frappe.utils.flt(r["qty"]), "s_warehouse": src, "t_warehouse": dst, "batch_no": r["batch_no"]})
        name = make_transfer(card.company, items, "Fabric Issue", card.name, "Fabric issued to cutting for %s" % card.name, True)
        refresh_issued(card.name)
        return name
    # shared helpers from production/summary.py: quantities read back from the ledger for reports. Needs lib_cutting.py (moved_qty).
    def live_cards(sales_order, style_item):
        filters = {"docstatus": 1, "status": ["not in", ("Superseded", "Cancelled")]}
        if sales_order:
            filters["sales_order"] = sales_order
        if style_item:
            filters["style_item"] = style_item
        return frappe.get_all("Production Card", filters=filters, pluck="name")


    def stage_qty(sales_order, style_item, colour, stages, purpose, process):
        """Sum of ledger quantity for stages of one order x style x colour across its live cards."""
        cards = live_cards(sales_order, style_item)
        if not cards:
            return 0
        cond = ""
        args = [tuple(cards), tuple(stages)]
        if colour:
            cond = cond + " and upper(colour) = upper(%s)"
            args.append(colour)
        if purpose:
            cond = cond + " and purpose = %s"
            args.append(purpose)
        if process:
            cond = cond + " and subcontract_process = %s"
            args.append(process)
        return frappe.utils.flt(frappe.db.sql("select ifnull(sum(qty), 0) from `tabProduction Movement` where production_card in %s and stage in %s" + cond, tuple(args))[0][0])


    def good_cut(sales_order, style_item, colour):
        return stage_qty(sales_order, style_item, colour, ["CUT"], None, None) - stage_qty(sales_order, style_item, colour, ["CUT_REJECT"], None, None)


    def fabric_usage(sales_order, style_item, colour, fabric_item):
        """[good garments cut, metres drawn net of remnants returned, actual consumption per garment] for one fabric."""
        cut = good_cut(sales_order, style_item, colour)
        net = 0.0
        for card in live_cards(sales_order, style_item):
            net = net + moved_qty(card, "Fabric Issue", fabric_item) - moved_qty(card, "Remnant Return", fabric_item)
        return [cut, net, (net / cut) if cut and net else None]
    flt = frappe.utils.flt

    def C(f, l, t="Data", w=100, o=None):
        d = {"fieldname": f, "label": l, "fieldtype": t, "width": w}
        if o:
            d["options"] = o
        return d

    columns = [C("po_date", "PO Date", "Date", 90), C("customer", "Buyer", "Link", 120, "Customer"), C("merchant", "Merchant", w=110), C("style_no", "Style", w=100),
               C("supplier", "Supplier", "Link", 130, "Supplier"), C("contract_no", "Supplier Contract", w=120), C("po", "Purchase Order", "Link", 120, "Purchase Order"),
               C("fabric", "Fabric", w=240), C("colour", "Colour", w=100), C("ordered", "Ordered", "Float", 90), C("uom", "Unit", w=60), C("price", "Price", "Currency", 80),
               C("value", "Ordered Value", "Currency", 110), C("delivery_date", "Delivery Date", "Date", 95), C("delay_days", "Delay (days)", "Int", 80), C("received_date", "Received On", "Date", 95),
               C("received", "Received", "Float", 90), C("over_short", "Over / Short", "Float", 90), C("over_short_pct", "Over / Short %", "Percent", 90), C("issued", "Issued", "Float", 90),
               C("balance", "Balance", "Float", 90), C("balance_pct_order", "% of Order", "Percent", 80), C("balance_pct_received", "% of Received", "Percent", 90),
               C("stock_value", "Stock Value", "Currency", 100), C("garment_qty", "Garment Qty", "Int", 90), C("cut_qty", "Cut Qty", "Int", 120), C("used_consumption", "Actual Used / pc", "Float", 150)]
    cond = ["o.docstatus = 1", "i.apparel_requisition_type = 'FR'"]
    args = {}
    for key, col in (("customer", "r.customer"), ("supplier", "o.supplier"), ("sales_order", "i.sales_order")):
        if filters.get(key):
            cond.append("%s = %%(%s)s" % (col, key))
            args[key] = filters.get(key)
    rows = frappe.db.sql("select o.name po, o.transaction_date po_date, o.supplier, o.apparel_supplier_contract_no contract_no, i.name poi, i.item_code, i.item_name, i.description, "
                         "i.stock_qty ordered, i.stock_uom uom, i.rate price, i.amount, i.schedule_date delivery_date, i.apparel_style_no style_no, i.apparel_colour colour, "
                         "i.apparel_requisition, i.material_request_item, i.sales_order, (select variant_of from `tabItem` where name = (select item_code from `tabSales Order Item` "
                         "where parent = i.sales_order and apparel_colour = i.apparel_colour limit 1)) style_item, r.customer, r.ordered_by from `tabPurchase Order Item` i "
                         "join `tabPurchase Order` o on o.name = i.parent left join `tabFabric Requisition` r on r.name = i.apparel_requisition where " + " and ".join(cond) +
                         " order by o.transaction_date, o.name", args, as_dict=True)
    stores = []
    for c in frappe.get_all("Company", pluck="name"):
        w = company_warehouse("store_warehouse_fabric", c)
        if w and w not in stores:
            stores.append(w)
    out = []
    for r in rows:
        prs = frappe.db.sql("select pr.name, pr.posting_date, pri.stock_qty from `tabPurchase Receipt Item` pri join `tabPurchase Receipt` pr on pr.name = pri.parent "
                            "where pri.purchase_order_item = %s and pr.docstatus = 1 order by pr.posting_date", (r.poi,), as_dict=True)
        received = sum([flt(p.stock_qty) for p in prs])
        first = prs[0].posting_date if prs else None
        batches = frappe.get_all("Batch", filters={"reference_doctype": "Purchase Receipt", "reference_name": ["in", [p.name for p in prs] or [""]]}, pluck="name")
        issued = 0.0
        if batches and stores:
            issued = flt(frappe.db.sql("select coalesce(-sum(e.qty), 0) from `tabSerial and Batch Entry` e join `tabSerial and Batch Bundle` b on b.name = e.parent "
                                       "where b.docstatus = 1 and b.is_cancelled = 0 and e.qty < 0 and e.batch_no in %s and e.warehouse in %s", (tuple(batches), tuple(stores)))[0][0])
        balance = received - issued
        merchant = frappe.db.get_value("User", r.ordered_by, "full_name") if r.ordered_by else None
        garment = frappe.db.get_value("Fabric Requisition Item", {"parent": r.apparel_requisition, "material_request_item": r.material_request_item}, "garment_qty") if r.apparel_requisition else None
        cut_qty = None
        used = None
        if r.sales_order and r.style_item:
            fu = fabric_usage(r.sales_order, r.style_item, r.colour, r.item_code)
            cut_qty = fu[0] or None
            used = fu[2]
        out.append({"po_date": r.po_date, "customer": r.customer, "merchant": merchant, "style_no": r.style_no, "supplier": r.supplier, "contract_no": r.contract_no, "po": r.po,
                    "fabric": (r.description or r.item_name or r.item_code)[:120], "colour": r.colour, "ordered": r.ordered, "uom": r.uom, "price": r.price, "value": r.amount,
                    "delivery_date": r.delivery_date, "delay_days": frappe.utils.date_diff(first, r.delivery_date) if first and r.delivery_date else None, "received_date": first,
                    "received": received, "over_short": received - flt(r.ordered), "over_short_pct": (received - flt(r.ordered)) * 100 / flt(r.ordered) if flt(r.ordered) else 0,
                    "issued": issued, "balance": balance, "balance_pct_order": balance * 100 / flt(r.ordered) if flt(r.ordered) else 0,
                    "balance_pct_received": balance * 100 / received if received else 0, "stock_value": balance * flt(r.price), "garment_qty": garment, "cut_qty": cut_qty, "used_consumption": used})
    return (columns, out)


data = list(main(filters))

def main(filters):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    getdate = frappe.utils.getdate

    def key(stype):
        return "t_" + "".join([c if c.isalnum() else "_" for c in stype.lower()])

    base = get_rules(None, None, None)
    types = [t for t in base if base[t]["gate"] != "No"]
    for t in frappe.get_all("Sample Requirement", filters={"enabled": 1, "gate": ["in", ["Required", "If Raised"]]}, pluck="sample_type"):
        if base.get(t) and base[t]["gate"] == "No" and t not in types:
            types.append(t)
    columns = [{"fieldname": "sales_order", "label": "Sales Order", "fieldtype": "Link", "options": "Sales Order", "width": 140},
               {"fieldname": "customer", "label": "Customer", "fieldtype": "Link", "options": "Customer", "width": 130},
               {"fieldname": "style_item", "label": "Style", "fieldtype": "Link", "options": "Item", "width": 120}, {"fieldname": "colour", "label": "Colour", "fieldtype": "Data", "width": 90}]
    for t in types:
        columns.append({"fieldname": key(t), "label": t, "fieldtype": "Data", "width": 110})
    columns.append({"fieldname": "next_due", "label": "Next Due", "fieldtype": "Date", "width": 100})
    columns.append({"fieldname": "overdue", "label": "Overdue", "fieldtype": "Int", "width": 70})
    columns.append({"fieldname": "gate", "label": "Bulk Gate", "fieldtype": "Data", "width": 90})
    so_filters = {"docstatus": 1}
    if filters.get("sales_order"):
        so_filters["name"] = filters.get("sales_order")
    if filters.get("customer"):
        so_filters["customer"] = filters.get("customer")
    today = getdate(frappe.utils.nowdate())
    rows = []
    for so in frappe.get_all("Sales Order", filters=so_filters, fields=["name", "customer"], order_by="transaction_date desc", limit=200):
        item_of = {}
        order = []
        for it in frappe.get_all("Sales Order Item", filters={"parent": so.name}, fields=["item_code", "apparel_colour"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of")
            if style:
                k = "%s|%s" % (style, (it.apparel_colour or "").strip())
                if k not in item_of:
                    item_of[k] = [style, (it.apparel_colour or "").strip(), it.item_code]
                    order.append(k)
        for k in order:
            style = item_of[k][0]
            colour = item_of[k][1]
            item_code = item_of[k][2]
            samples = frappe.get_all("Sample Approval", filters=scope_filters(so.name, style), fields=["name", "sample_type", "status", "colour", "due_date"])
            row = {"sales_order": so.name, "customer": so.customer, "style_item": style, "colour": colour}
            dues = []
            overdue = 0
            rules = get_rules(so.customer, so.name, style)
            for stype in types:
                rule = rules[stype]
                gate_type = effective_gate(rule, so.name)
                mine = [s for s in samples if s.sample_type == stype and (not rule["per_colour"] or not (s.colour or "").strip() or norm(s.colour) == norm(colour))]
                bad = [s for s in mine if s.status not in GATE_OK]
                if bad:
                    row[key(stype)] = bad[0].status
                elif mine:
                    row[key(stype)] = "Approved"
                else:
                    row[key(stype)] = "Missing" if gate_type == "Required" else "-"
                for s in bad:
                    if s.due_date:
                        dues.append(getdate(s.due_date))
                        overdue = overdue + (1 if getdate(s.due_date) < today else 0)
            gate = run_script("arinox_work_order_api_get_bulk_gate", production_item=item_code, sales_order=so.name).get("arinox_result")
            row["next_due"] = min(dues) if dues else None
            row["overdue"] = overdue
            row["gate"] = "Open" if not gate["blockers"] else "Blocked"
            if filters.get("only_blocked") and row["gate"] == "Open":
                continue
            rows.append(row)
    return (columns, rows)


data = list(main(filters))

def main(filters):

    def execute(filters):
        filters = filters
        columns = [{'fieldname': 'line', 'label': 'Line', 'fieldtype': 'Link', 'options': 'Workstation', 'width': 160}, {'fieldname': 'production_card', 'label': 'Production Card', 'fieldtype': 'Link', 'options': 'Production Card', 'width': 130}, {'fieldname': 'style_no', 'label': 'Style', 'fieldtype': 'Data', 'width': 110}, {'fieldname': 'colour', 'label': 'Colour', 'fieldtype': 'Data', 'width': 90}, {'fieldname': 'loaded', 'label': 'Loaded', 'fieldtype': 'Int', 'width': 80}, {'fieldname': 'sewn', 'label': 'Sewn', 'fieldtype': 'Int', 'width': 80}, {'fieldname': 'rejected', 'label': 'Rejected', 'fieldtype': 'Int', 'width': 80}, {'fieldname': 'wip', 'label': 'WIP', 'fieldtype': 'Int', 'width': 80}]
        cond = ''
        args = {}
        for key in ('line', 'production_card'):
            if filters.get(key):
                cond += f' and m.{key} = %({key})s'
                args[key] = filters[key]
        rows = frappe.db.sql(f"select m.line, m.production_card, c.style_no, m.colour,\n    \t\tsum(case when m.stage = 'SEW_IN' then m.qty else 0 end) loaded, sum(case when m.stage = 'SEW_OUT' then m.qty else 0 end) sewn,\n    \t\tsum(case when m.stage = 'SEW_REJECT' then m.qty else 0 end) rejected\n    \t\tfrom `tabProduction Movement` m join `tabProduction Card` c on c.name = m.production_card\n    \t\twhere m.stage in ('SEW_IN', 'SEW_OUT', 'SEW_REJECT') and m.line is not null{cond}\n    \t\tgroup by m.line, m.production_card, m.colour order by m.line, c.style_no, m.colour", args, as_dict=True)
        for r in rows:
            r.wip = r.loaded - r.sewn - r.rejected
        return (columns, [r for r in rows if r.loaded or r.wip])
    return execute(filters)
data = list(main(filters))
